From c18d7b37ea12fd3b61a928be607f2c126b047306 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 21:08:35 +0100
Subject: [PATCH] scripting: expose the shell type to scripts

Scripts had no way to tell which shell they were running in, so a
layout or update script couldn't skip itself outside Plasma Desktop.
Add a read-only shell property with the shell package's plugin id.

BUG: 515789
---
 shell/scripting/appinterface.cpp | 5 +++++
 shell/scripting/appinterface.h   | 3 +++
 shell/scripting/scriptengine.cpp | 1 +
 3 files changed, 9 insertions(+)

diff --git a/shell/scripting/appinterface.cpp b/shell/scripting/appinterface.cpp
index f421fc6786..74150d17a8 100644
--- a/shell/scripting/appinterface.cpp
+++ b/shell/scripting/appinterface.cpp
@@ -114,6 +114,11 @@ QString AppInterface::languageId() const
     return QLocale::system().bcp47Name().section(QLatin1Char('-'), 0, 0);
 }

+QString AppInterface::shell() const
+{
+    return m_env->corona()->kPackage().metadata().pluginId();
+}
+
 bool AppInterface::multihead() const
 {
     return false;
diff --git a/shell/scripting/appinterface.h b/shell/scripting/appinterface.h
index 36ef0dd13b..567f1ffce2 100644
--- a/shell/scripting/appinterface.h
+++ b/shell/scripting/appinterface.h
@@ -42,6 +42,7 @@ class AppInterface : public QObject
     Q_PROPERTY(QString locale READ locale)
     Q_PROPERTY(QString language READ language)
     Q_PROPERTY(QString languageId READ languageId)
+    Q_PROPERTY(QString shell READ shell)

 public:
     explicit AppInterface(ScriptEngine *env);
@@ -67,6 +68,8 @@ public:
     QString language() const;
     QString languageId() const;

+    QString shell() const;
+
     bool multihead() const;
     int multiheadScreen() const;

diff --git a/shell/scripting/scriptengine.cpp b/shell/scripting/scriptengine.cpp
index 8a5728cb5b..6a4409e1d1 100644
--- a/shell/scripting/scriptengine.cpp
+++ b/shell/scripting/scriptengine.cpp
@@ -121,6 +121,7 @@ void ScriptEngine::setupEngine()
                 get locale() {return __AppInterface.locale;},\
                 get language() {return __AppInterface.language;},\
                 get languageId() {return __AppInterface.languageId;},\
+                get shell() {return __AppInterface.shell;},\
             }"_s);
     Q_ASSERT(!res.isError());
     // methods from AppInterface
-- 
